import{_ as r,o as e,c as a,ai as o}from"./chunks/framework.ampVZV4B.js";const m=JSON.parse('{"title":"C# · 03 框架与生态","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/csharp/03-frameworks.md","filePath":"tech-system/backend/csharp/03-frameworks.md"}'),n={name:"tech-system/backend/csharp/03-frameworks.md"};function s(i,t,l,d,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="c-·-03-框架与生态" tabindex="-1">C# · 03 框架与生态 <a class="header-anchor" href="#c-·-03-框架与生态" aria-label="Permalink to “C# · 03 框架与生态”">​</a></h1><blockquote><p>中小场景常见：<strong>ASP.NET 做 Web</strong>、<strong>WinForm/WPF 做桌面</strong>。先认门类，再谈深挖。</p></blockquote><h2 id="_1-asp-net-core" tabindex="-1">1. ASP.NET Core <a class="header-anchor" href="#_1-asp-net-core" aria-label="Permalink to “1. ASP.NET Core”">​</a></h2><ul><li>现代 .NET Web 主线：API、MVC、中间件模型</li><li>有 Java Spring Boot 经验时，路由 / DI / 配置思路可迁移</li><li>适合：中小 Web 后台、远程 .NET 维护/二开</li></ul><p><strong>判断：</strong> 要写 C# 服务端，优先认这条，而不是死磕老 WebForms。</p><h2 id="_2-老-asp-net-webforms-存量" tabindex="-1">2. 老 ASP.NET / WebForms（存量） <a class="header-anchor" href="#_2-老-asp-net-webforms-存量" aria-label="Permalink to “2. 老 ASP.NET / WebForms（存量）”">​</a></h2><ul><li>本地信息化、早期外包项目里仍可能遇到</li><li>目标是 <strong>能读、能改、能修 bug</strong>，不是当新项目首选</li><li>页面生命周期、ViewState 等概念与现代 MVC 不同，撞上再查</li></ul><h2 id="_3-winforms" tabindex="-1">3. WinForms <a class="header-anchor" href="#_3-winforms" aria-label="Permalink to “3. WinForms”">​</a></h2><ul><li>Windows 桌面快速出活，工厂工具、简单上位机常见</li><li>UI 老但存量大；中小要的是稳定能跑，不是好看</li></ul><p><strong>判断：</strong> 洛阳/工控旁路撞上桌面需求时，WinForms 仍是高频现实。</p><h2 id="_4-wpf" tabindex="-1">4. WPF <a class="header-anchor" href="#_4-wpf" aria-label="Permalink to “4. WPF”">​</a></h2><ul><li>比 WinForms 更现代的 Windows UI（XAML、数据绑定）</li><li>上手成本高于 WinForms；新桌面可考虑，老项目看团队存量</li></ul><hr><h2 id="_5-和-electron-怎么选-对我" tabindex="-1">5. 和 Electron 怎么选（对我） <a class="header-anchor" href="#_5-和-electron-怎么选-对我" aria-label="Permalink to “5. 和 Electron 怎么选（对我）”">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>更倾向</th></tr></thead><tbody><tr><td>已有 Vue/TS，要跨平台 UI</td><td><strong>Electron</strong></td></tr><tr><td>强绑 Windows 控件 / 现场驱动 / 存量 WinForms</td><td><strong>WinForms/WPF</strong></td></tr><tr><td>既要本地设备又要现代 Web UI</td><td>Electron 本地服务 + 可选 C# 驱动桥（看驱动 API）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>新的中小 Web（恰好 .NET 团队）</td><td>ASP.NET Core</td></tr><tr><td>老 WebForms</td><td>维护为主</td></tr><tr><td>工厂小工具桌面</td><td>WinForms 常见</td></tr><tr><td>我的默认主 Web</td><td>仍是 <strong>Java + Spring Boot</strong></td></tr></tbody></table><p>下一篇：<a href="./04-engineering.html">04 工程实践</a></p>',17)])])}const _=r(n,[["render",s]]);export{m as __pageData,_ as default};
